async getConversation({ sessionId, userId, }) {
    const conversation = await this.aiConversationsRepo.findOne({
        filter: {
            sessionId,
            category: 'chat',
        },
    });
    if (!userId) {
        return conversation;
    }
    if (!conversation) {
        return null;
    }
    const ownershipCheck = await this.aiConversationsRepo.count({
        filter: { sessionId, userId },
    });
    if (ownershipCheck) {
        return conversation;
    }
    else {
        return null;
    }
}

const refresh = useCallback(
  (
    conversationId: string,
    targetChat: Chat<AIChatMessage>,
    options: { updateRead?: boolean } = {},
  ) => {
    const updateRead = options.updateRead === true;
    const requestKey = `${conversationId}:${updateRead ? 'read' : 'peek'}`;
    const pending = pendingRequestsRef.current.get(requestKey);
    if (pending) return pending;

    const request = getConversationMessages(conversationId, { updateRead })
      .then((messages) => {
        const reconciled = reconcileRefreshedMessages(
          targetChat.messages,
          messages,
        );
        targetChat.messages = reconciled;
        return reconciled;
      })
      .finally(() => pendingRequestsRef.current.delete(requestKey));
    pendingRequestsRef.current.set(requestKey, request);
    return request;
  },
  [getConversationMessages],
);

# Register application AI Employees and Tools from server/ai

Application Employees and Tools are defined under `server/ai/employees/` and `server/ai/tools/`, aggregated with static imports in `server/ai/index.ts`, and registered from the application's Server Provider.

Employee and Tool implementations use `defineAIEmployee()` and `defineTools()`. Put the Employee prompt in its `systemPrompt` field and configure its Skill and Tool names explicitly.

Use the public `AIResourceRegistrar` contract exported by `@nocobase/app-plugin-ai-employee/server`:

```ts
