export function defineAuthorizationResource(name, configure) {
    if (!name)
        throw new TypeError('A resource name is required');
    const result = configure(new AuthorizationResourceBuilder({
        name,
        title: name,
        group: '',
        actions: [],
    }));
    const definition = result.build();
    if (!definition.group || !definition.actions.length)
        throw new TypeError('A resource requires a group and actions');
    return new AuthorizationResourceBuilder(definition);
}

export function composedGrants(provider, resources, constraints) {
    const expand = async (grants, input) => Promise.all(grants
        .flatMap((grant) => resources.expand(grant))
        .map(async (grant) => {
        if (!grant.origin?.scopeKey)
            return grant;
        const branchConstraints = await constraints.resolve({
            ...input,
            ...grant.origin,
        });
        return {
            ...grant,
            policy: {
                ...grant.policy,
                type: grant.policy?.type ?? 'database',
                branchConstraints,
            },
        };
    }));

export function databaseAuthorization(database) {
    const api = new DatabaseAuthorizationService();
    const collections = api.collections;
    return {
        id: 'database',
        composeConditions: (checks) => ({
            database: composeDatabasePolicies(checks),
        }),
        requiresGrants: true,
        authorizationApi: { db: api },
        setup(authz) {
            for (const policy of [
                allRecords(),
                customFilter(),
                recordsIOwn(),
                recordsICreated(),
            ])
                authz.recordAccess.add(policy);
            // Collection metadata comes from the connection the host passed in; an
            // application that installed the plugin without one grants nothing.
            const authorizer = new DatabaseResourceAuthorizer({
                collections,
                recordAccess: authz.recordAccess,
                ...(authz.connection
                    ? {
                        resolveCollection: collectionResolver(authz.connection, database),
                    }
                    : {}),
            });
            authz.resourceTypes.add({
                resourceType: 'database.collection',
                items: collections,
                actions: ['read', 'create', 'update', 'delete'].map((name) => ({
                    name,
                    authorize: (request, context) => authorizer.authorize({
                        ...request,
                        params: request.params,
                    }, context.grants, context.constraints),
                    authorizeUnrestricted: (request) => authorizer.authorizeUnrestricted({
                        ...request,
                        params: request.params,
                    }),
                })),
            });
        },
    };
}

