/**
 * The reusable data permission for reading materials.
 *
 * `.options(...)` makes both scopes selectable in the permission-set editor and
 * `.default(...)` selects the reader scope, so a set that grants `read`
 * without naming a scope can only ever read reader rows.
 */
export const materialsData = defineDatabasePermission((permission) =>
  permission
    .collection<Material>(MATERIALS_COLLECTION)
    .title({ key: 'materials.resource.data', ns: 'nb3-factory' })
    .options(materialsReader, materialsAll)
    .default(materialsReader)
    .read((read) => read.fields(...MATERIAL_FIELDS)),
);

export function registerMaterialsAuthorization(
  authz: AppAuthorizationService,
): void {
  if (!authz.resourceGroups.has(MATERIALS_GROUP)) {
    authz.resourceGroups.add({
      name: MATERIALS_GROUP,
      category: 'business',
      title: { key: 'materials.group', ns: 'nb3-factory' },
    });
  }

  if (!authz.db.collections.has(MATERIALS_COLLECTION)) {
    authz.db.collections.add({
      name: MATERIALS_COLLECTION,
      title: { key: 'materials.resource.data', ns: 'nb3-factory' },
    });
  }

  if (!authz.recordAccess.get(MATERIALS_READER_SCOPE)) {
    authz.recordAccess.add(materialsReader);
  }

  if (!authz.recordAccess.get(MATERIALS_MANAGER_SCOPE)) {
    authz.recordAccess.add(materialsAll);
  }

  // The page and the read operation are independent grants: a set can open the
  // page without reading anything, which the page reports truthfully.
  authz.pages.add({
    name: MATERIALS_PAGE,
    title: { key: 'materials.page.assistant', ns: 'nb3-factory' },
    actions: ['access'],
    actionTitles: {
      access: { key: 'materials.action.access', ns: 'nb3-factory' },
    },
  });

  materialsResource.register(authz.resources);

private async readPolicy(
  scope: AuthorizationScope,
): Promise<RepositoryPolicy | null> {
  const decision = await scope.authorize({
    resource: { type: 'resource', id: MATERIALS_RESOURCE },
    action: 'read',
  });

  if (decision.effect === 'deny') {
    return null;
  }

  const policy = decision.conditions?.database?.[MATERIALS_COLLECTION];
  if (!policy || policy.read === false) {
    return null;
  }

  return policy;
}

private repositoryFor(policy: RepositoryPolicy) {
  return this.resolver
    .resolve(databaseManagerToken)
    .repository<Material>(MATERIALS_COLLECTION)
    .withPolicy(policy);
}

withPolicy(policy, principal) {
    // A Repository handed out by a policy-bound Connection is still a
    // DefaultRepository, and the Connection types it as `Repository`, so this
    // method stays reachable. Replacing the binding there would hand back an
    // unrestricted Repository and undo the Connection's authorization, so
    // rebinding is refused rather than allowed to widen. Tightening further
    // is what `narrow` is for.
    if (this.options.policy) {
        invalid('INVALID_POLICY', 'This Repository already has a bound Policy. Use narrow() to tighten it; a Policy cannot be replaced.', { collection: this.options.collection });
    }
    const input = typeof policy === 'function' ? policy(principal) : policy;
    return new DefaultRepository({
        ...this.options,
        policy: normalizeRepositoryPolicy(input),
    });
}

/** Intersect the caller filter with a Policy scope without flattening either side. */
export function combinePolicyFilter(caller, policy, collection) {
    if (!caller)
        return policy;
    if (!policy)
        return caller;
    return {
        kind: 'filter',
        version: 1,
        collection,
        root: {
            kind: 'group',
            logic: 'and',
            items: [caller.root, policy.root],
        },
    };
}

