export default defineSeed({
  name: '202609250001_materials',
  transaction: true,
  async run(context) {
    const { query } = context;
    const now = new Date();
    const materials = context.repository<MaterialRow>('materials');

    for (const fixture of MATERIAL_FIXTURES) {
      const existing = await materials.findOne({
        filter: { title: fixture.title },
      });
      if (existing) continue;
      await materials.createOne({
        values: {
          title: fixture.title,
          summary: fixture.summary,
          content: fixture.content,
          accessLevel: fixture.accessLevel,
          source: fixture.source,
          createdAt: now,
        },
      });
    }

    for (const set of [materialsReaderSet, materialsManagerSet]) {
      const existing = await query
        .selectFrom('authorizationPermissionSets')
        .select('key')
        .where('key', '=', set.key)
        .executeTakeFirst();
      // Preserve a permission set an administrator has already redefined.
      if (existing) continue;
      await query
        .insertInto('authorizationPermissionSets')
        .values({
          id: set.key,
          key: set.key,
          title: encodeAuthorizationTitle(set.title),
          grants: JSON.stringify(set.grants),
          createdAt: now,
          updatedAt: now,
        })
        .execute();
    }

    const assignmentId = `${MATERIALS_READER_AUDIENCE.type}:${MATERIALS_READER_AUDIENCE.id}:${MATERIALS_READER_SET}`;
    const existingAssignment = await query
      .selectFrom('authorizationPermissionSetAssignments')
      .select('id')
      .where('id', '=', assignmentId)
      .executeTakeFirst();
    if (!existingAssignment) {
      await query
        .insertInto('authorizationPermissionSetAssignments')
        .values({
          id: assignmentId,
          subjectType: MATERIALS_READER_AUDIENCE.type,
          subjectId: MATERIALS_READER_AUDIENCE.id,
          permissionSetKey: MATERIALS_READER_SET,
          createdAt: now,
          updatedAt: now,
        })
        .execute();
    }
